def make_cases():
    cases = []
    for family_index, family in enumerate(FAMILIES):
        for within in range(10):
            label = "legitimate" if within < 4 else "fraudulent" if within < 8 else "borderline"
            person = PEOPLE[(family_index * 3 + within) % len(PEOPLE)]
            amount = 74500 + family_index * 13900 + within * 2875
            ref = f"Q{family_index + 31:02d}-{within + 1:02d}"
            title = f"{family['topic'].capitalize()} support for {person}"
            story = f"{family['story']} The file is {ref}; the requested total is ₹{amount:,}."
            docs = []
            if label == "legitimate":
                relation = "supporting"
                if within == 1:
                    # A true campaign whose proof package is incomplete.
                    content = f"{family['support']} File {ref}. The final authorization stamp is still being processed."
                    docs.append({"doc_type": family["source"].upper(), "title": f"Preliminary record {ref}", "content": content})
                else:
                    docs.append({"doc_type": family["source"].upper(), "title": f"Verified source record {ref}", "content": f"{family['support']} File {ref}. Applicant: {person}. Amount requested: ₹{amount:,}."})
                if within == 2:
                    docs.append({"doc_type": "SUPPLEMENTAL_COST_NOTE", "title": f"Cost explanation {ref}", "content": f"The total includes access, transport, replacement, or preservation requirements described for {family['topic']}; unit costs are itemized for the stated period."})
                rationale = "Underlying need and use are legitimate; documentation may be incomplete or unusual." if within == 1 else "Independent records support the campaign need and requested use."
            elif label == "fraudulent":
                relation = "conflicting_or_misrepresented"
                story += " " + family["fraud_story"]
                docs = [
                    {"doc_type": "PRIMARY_RECORD", "title": f"Primary record {ref}", "content": f"{family['fraud_docs'][0]} Reference {ref}; person recorded: {person}."},
                    {"doc_type": "INDEPENDENT_REGISTER", "title": f"Independent register extract {ref}", "content": f"{family['fraud_docs'][1]} Cross-reference {ref}; name on request: {person}."},
                ]
                # Two of the four deceptive cases per family carry polished,
                # mutually consistent paperwork while a separate source reveals
                # prior settlement, ineligibility, or a hidden restriction.
                if within in (6, 7):
                    docs[0]["content"] += f" All fields reconcile to ₹{amount:,} and the named applicant."
                    docs[1]["content"] += f" The record copy repeats the same applicant, total ₹{amount:,}, and reference."
                rationale = "The complete dossier contains a material mismatch, prior settlement, access restriction, or a consistent-looking claim contradicted by an independent source."
            else:
                relation = "unresolved"
                story = f"{family['border_story']} The request file is {ref} and the provisional budget is ₹{amount:,}."
                docs = [{"doc_type": family["source"].upper(), "title": f"Preliminary inquiry {ref}", "content": f"{family['border_doc']} File {ref}. No final amount or approval is recorded."}]
                rationale = "The facts are unresolved; requesting the missing authorization, quote, or status is preferable to accusing or rejecting."

            cases.append({
                "case_id": f"E150-{len(cases) + 1:03d}", "ground_truth": label,
                "scenario_family": family["family"], "document_source": family["source"],
                "evidence_design": relation, "synthetic": True,
                "adjudication_note": rationale,
                "input": {"title": title, "category": family["category"], "story": story,
                          "goal_amount": amount, "beneficiary_name": person,
                          "beneficiary_type": "SELF", "city": "Udaipur", "state": "Rajasthan",
                          "documents": docs},
            })
    return cases


if __name__ == "__main__":
    rows = make_cases()
    OUT.write_text("".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows), encoding="utf-8")
    print(f"Wrote {len(rows)} independent synthetic cases to {OUT}")
